.pl-table tr.pl-total td:first-child{border-radius:8px 0 0 8px}
.pl-table tr.pl-total td:last-child{border-radius:0 8px 8px 0}
.pl-table td.val{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}
.pl-table td.val.neg{color:var(--red);font-weight:600}
.pl-table td.val.pos{color:var(--green);font-weight:600}
